public class Main {
    private static final int DEFAULT_TIMEOUT_MILLIS = 10000;
    private static final int DEFAULT_MAX_RESPONSE_BYTES = 65536;

    public static SSLContext createDefaultSSLContext() throws GeneralSecurityException {
        SSLContext context = SSLContext.getInstance("TLS");
        context.init(null, null, new SecureRandom());
        return context;
    }

    public static SSLContext createSSLContext(String trustStorePath, char[] trustStorePassword) throws GeneralSecurityException, IOException {
        if (trustStorePath == null || trustStorePath.trim().isEmpty()) {
            return createDefaultSSLContext();
        }
        KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
        char[] password = trustStorePassword == null ? new char[0] : trustStorePassword;
        try (InputStream in = new FileInputStream(trustStorePath)) {
            keyStore.load(in, password);
        }
        TrustManagerFactory trustManagerFactory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        trustManagerFactory.init(keyStore);
        SSLContext context = SSLContext.getInstance("TLS");
        context.init(null, trustManagerFactory.getTrustManagers(), new SecureRandom());
        return context;
    }

    public static SSLSocket createSecureSocket(String host, int port, int timeoutMillis, SSLContext context) throws IOException, GeneralSecurityException {
        if (host == null || host.trim().isEmpty()) throw new IllegalArgumentException("host must not be null or blank");
        if (port <= 0 || port > 65535) throw new IllegalArgumentException("port must be between 1 and 65535");
        if (timeoutMillis < 0) throw new IllegalArgumentException("timeoutMillis must be non-negative");
        SSLContext sslContext = context == null ? createDefaultSSLContext() : context;
        SSLSocket socket = (SSLSocket) sslContext.getSocketFactory().createSocket();
        socket.connect(new InetSocketAddress(host, port), timeoutMillis);
        socket.setSoTimeout(timeoutMillis);
        configureSocket(socket);
        socket.startHandshake();
        return socket;
    }

    public static void configureSocket(SSLSocket socket) throws IOException {
        if (socket == null) throw new IllegalArgumentException("socket must not be null");
        SSLParameters parameters = socket.getSSLParameters();
        parameters.setEndpointIdentificationAlgorithm("HTTPS");
        String[] protocols = selectSecureProtocols(socket);
        if (protocols.length > 0) parameters.setProtocols(protocols);
        socket.setSSLParameters(parameters);
    }

    public static String[] selectSecureProtocols(SSLSocket socket) {
        if (socket == null) throw new IllegalArgumentException("socket must not be null");
        Set<String> supported = new LinkedHashSet<>(Arrays.asList(socket.getSupportedProtocols()));
        List<String> selected = new ArrayList<>();
        String[] preferred = {"TLSv1.3", "TLSv1.2"};
        for (String protocol : preferred) {
            if (supported.contains(protocol)) selected.add(protocol);
        }
        if (selected.isEmpty()) {
            return socket.getEnabledProtocols();
        }
        return selected.toArray(new String[0]);
    }

    public static ConnectionInfo establishSecureConnection(String host, int port, int timeoutMillis, String optionalRequest, String trustStorePath, char[] trustStorePassword) throws IOException, GeneralSecurityException {
        long started = System.nanoTime();
        SSLContext context = createSSLContext(trustStorePath, trustStorePassword);
        SSLSocket socket = createSecureSocket(host, port, timeoutMillis, context);
        try {
            SSLSession session = socket.getSession();
            X509Certificate[] peerCertificates = session.getPeerCertificates();
            String response = null;
            if (optionalRequest != null && !optionalRequest.trim().isEmpty()) {
                response = exchange(socket, optionalRequest, DEFAULT_MAX_RESPONSE_BYTES);
            }
            long handshakeTimeMillis = (System.nanoTime() - started) / 1_000_000L;
            return new ConnectionInfo(host, port, session.getProtocol(), session.getCipherSuite(), peerCertificates, session.getPeerPrincipal(), session.getLocalPrincipal(), handshakeTimeMillis, response);
        } finally {
            socket.close();
        }
    }

